<?php require 'config.php'; need(['radiographer','doctor','nurse']); check();$rad=in_array(user()['role'],['radiographer','admin']);$msg=$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&$rad){
  if(isset($_POST['exam'])){try{$pdo->prepare('INSERT INTO imaging_exams(name,modality,price) VALUES(?,?,?)')->execute([trim($_POST['exam']),$_POST['modality'],max(0,(float)$_POST['price'])]);$msg='Exam added.';}catch(PDOException $x){$err='That exam already exists.';}}
  else{$o=$pdo->prepare("SELECT * FROM imaging_orders WHERE id=? AND status='queued'");$o->execute([(int)($_POST['order']??0)]);$o=$o->fetch();
    if($o&&isset($_POST['cancel'])){$pdo->prepare("UPDATE imaging_orders SET status='cancelled' WHERE id=?")->execute([$o['id']]);advance($o['visit_id'],'consultation');audit('imaging cancelled '.$o['id']);$msg='Order cancelled.';}
    elseif($o){if(trim($_POST['findings'])===''||trim($_POST['impression'])==='')$err='Enter the findings and the impression.';
      else{$pdo->prepare("UPDATE imaging_orders SET status='reported',findings=?,impression=?,performed_by=?,reported_at=NOW() WHERE id=?")->execute([trim($_POST['findings']),trim($_POST['impression']),user()['id'],$o['id']]);advance($o['visit_id'],'consultation');audit('imaging reported '.$o['id']);header('Location: slip.php?kind=imaging&visit='.$o['visit_id'].'&back=imaging.php');exit;}}}}
head('Imaging');if($msg)echo '<p class=ok>'.e($msg).'</p>';if($err)echo '<p class=err>'.e($err).'</p>';
$rows=$pdo->query("SELECT o.*,e.name en,e.modality,p.patient_no,p.first_name,p.last_name,v.reason,u.name doc FROM imaging_orders o JOIN imaging_exams e ON e.id=o.exam_id JOIN visits v ON v.id=o.visit_id JOIN patients p ON p.id=v.patient_id LEFT JOIN users u ON u.id=o.ordered_by WHERE o.status='queued' ORDER BY o.id")->fetchAll();
echo '<h3>Waiting for imaging</h3>';if(!$rows)echo '<div class=card><p>No imaging requests waiting. Doctors order exams on the consultation page.</p></div>';
foreach($rows as $o){echo '<div class=card><b>'.e($o['en']).'</b> ('.e($o['modality']).') for '.e($o['patient_no'].' '.$o['first_name'].' '.$o['last_name']).'<br><small>Ordered by '.e($o['doc']).' | Reason: '.e($o['reason']).' | Clinical info: '.e($o['clinical_info']).'</small>';
  if($rad)echo '<form method=post>'.field().'<input type=hidden name=order value='.$o['id'].'><label>Findings</label><textarea name=findings></textarea><label>Impression</label><textarea name=impression></textarea><button>Save report and print</button> <button name=cancel value=1 style="background:#a23b2a" onclick="return confirm(\'Cancel this order?\')">Cancel order</button></form>';
  echo '</div>';}?>
<div class=card><h3>Recent reports</h3><table><tr><th>Patient<th>Exam<th>Impression<th>Reported<th></tr>
<?php foreach($pdo->query("SELECT o.visit_id,o.impression,o.reported_at,e.name,p.patient_no,p.first_name,p.last_name FROM imaging_orders o JOIN imaging_exams e ON e.id=o.exam_id JOIN visits v ON v.id=o.visit_id JOIN patients p ON p.id=v.patient_id WHERE o.status='reported' ORDER BY o.id DESC LIMIT 30") as $o)echo '<tr><td>'.e($o['patient_no'].' '.$o['first_name'].' '.$o['last_name']).'<td>'.e($o['name']).'<td>'.e($o['impression']).'<td>'.substr($o['reported_at'],0,16).'<td><a target=_blank href="slip.php?kind=imaging&visit='.$o['visit_id'].'&back=imaging.php">Print</a>';?></table></div>
<?php if($rad):?><div class=card><h3>Add an exam to the catalogue</h3><form method=post class=g><?=field()?><div><input name=exam placeholder="Exam name" required></div><div><select name=modality><option>X-ray<option>Ultrasound<option>CT scan<option>Other</select></div><div><input name=price type=number step=0.01 min=0 placeholder="Price (KES)"></div><div><button style="margin:0">Add</button></div></form></div><?php endif;foot();
